#!/usr/bin/env python3
"""The quest tab's five pages: write every generated file for them.

    python3 tools/genquesttab.py            # write the files and take interface ids
    python3 tools/genquesttab.py --check     # exit 1 if anything would change

THE TAB. The quest journal slot (^tab_quest_journal) shows one of five side interfaces, each with the
same row of five stone buttons across the top - the lit one is the page you are on - and a title:

  0 questtab_summary      Character Summary - name, levels, XP, quests, the collection log, game mode
  1 questlist             Quests - the quest list itself, GENERATED by LostCityServer
                          tools/models/genquest474.py, which lays it out under the button row
  2 questtab_collection   Collection Log - progress per collection log tab, the latest item, a button
  3 questtab_pstats       Player Statistics - a table of counters (player/scripts/player_stats.rs2)
  4 questtab_sstats       Server Statistics - players online, the time, uptime, and quick actions

Pressing a button is if_settab with the other interface (questtab/scripts/questtab.rs2 fills its
texts first), so each page is an ordinary side interface and nothing is hidden or shown.

WHAT THIS WRITES
  * sprites/questtab_icons.png    the five 15x15 button icons: the Quests star from the world map's
                                  quest icon (mapfunction 6), and the same star hue-shifted for the
                                  other four - purple, green, red and gold - as Old School gives each
                                  of its quest tab pages the same gem in its own colour
  * sprites/questtab_tab.png      the 36x24 button stones - at rest, lit, under the mouse - and
  * sprites/questtab_button.png   the 182x26 wide button: both cut from 377's own grey and red
                                  combat-style stones (combatboxes), which is what a pressable
                                  button looks like everywhere else in this client
  * scripts/questtab/interfaces/questtab_{summary,collection,pstats,sstats}.if
  * scripts/interfaces/questlist.if    ONLY its own marked block (the button row), put back in the
                                  same place - immediately before [qp] - so the three generators
                                  that share that file (genquest474, genbosskills, gencollectionlog)
                                  can run in any order and it comes out the same
  * scripts/questtab/configs/questtab.constant, questtab.enum   page numbers and the Collection Log
                                  rows' components, which the script reaches by number
  * scripts/questtab/scripts/questtab_tabs.rs2    the button row's triggers and ~questtab_settab
  * pack/interface.pack, interface.order    ids, by way of tools/ifids.py

The collection log's tab count and names come from tools/collectionlogspec.json, so a fifth tab
there is a fifth row here on the next run.
"""
import colorsys, json, os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import ifids

C = os.path.dirname(HERE)
SPRITES = os.path.join(C, 'sprites')
DIR = os.path.join(C, 'scripts', 'questtab')
QUESTLIST = os.path.join(C, 'scripts', 'interfaces', 'questlist.if')
CLOGSPEC = os.path.join(C, 'tools', 'collectionlogspec.json')
KEY = (255, 0, 255)
OUTLINE, BEVEL = (46, 43, 35), (114, 100, 81)   # combatboxes' stone: its outline and bevel line

# ------------------------------------------------------------------------------------ the pages
# (constant, interface, button option / title)
PAGES = [('summary', 'questtab_summary', 'Character Summary'),
         ('quests', 'questlist', 'Quests'),
         ('collection', 'questtab_collection', 'Collection Log'),
         ('pstats', 'questtab_pstats', 'Player Statistics'),
         ('sstats', 'questtab_sstats', 'Server Statistics')]

# ------------------------------------------------------------------------------------ geometry
# The side panel is 190x261. The button row is five 36x24 stones a pixel apart, 3px in from each
# side; the title sits under it where 474's "Quest Points" did above the list, and every page's
# body starts at BODY_TOP. genquest474.py imports these so the quest list lines up with the rest.
TAB_X, TAB_Y, TAB_W, TAB_H, TAB_PITCH = 3, 3, 36, 24, 37
TITLE_X, TITLE_Y, TITLE_W, TITLE_H = 6, 30, 178, 15
BODY_TOP, BODY_BOTTOM = 46, 257
BOX_X, BOX_W = 4, 182

# 474's title orange (the quest list's "Quest Points" is this colour), the client's text orange,
# and the rest of the palette the pages use.
TITLE = '0xEB981F'
ORANGE, WHITE, YELLOW, GREEN = '0xFF981F', '0xFFFFFF', '0xFFFF00', '0x00FF00'
# The stone buttons' own two edge colours (combatboxes): the dark outline and the brown bevel. A box
# is drawn in the same two, the other way up - dark along the top and left, brown along the bottom
# and right - so a box reads as set INTO the stone and a button as standing out of it.
EDGE, RIM = '0x2E2B23', '0x726451'
RULE = '0x4A4033'
TRACK = '0x1E1A14'


# ------------------------------------------------------------------------------------ sprites
def load_rgb(name):
    from PIL import Image
    return Image.open(os.path.join(SPRITES, name + '.png')).convert('RGB')


def icons():
    """The five button icons, in page order."""
    star = load_rgb('mapfunction').crop((90, 0, 105, 15))

    def is_star(p):
        r, g, b = p
        return b > r + 30 and b > g + 20          # the star's five blues; the grey coin is not

    def recolour(hue, sat=1.0, val=1.0):
        im = star.copy()
        px = im.load()
        for y in range(15):
            for x in range(15):
                p = px[x, y]
                if p != KEY and is_star(p):
                    h, s, v = colorsys.rgb_to_hsv(*(c / 255 for c in p))
                    r, g, b = colorsys.hsv_to_rgb(hue / 360, min(1, s * sat), min(1, v * val))
                    px[x, y] = (round(r * 255), round(g * 255), round(b * 255))
        return im
    return [recolour(285, 1.0, 0.95), star, recolour(125, 1.05, 0.8), recolour(0, 1.05, 0.9),
            recolour(45, 1.1, 0.95)]


def stone(src, w, h, lift=0):
    """A w x h button cut from a combatboxes stone: the notched corners as they are, the edges and
    the face TILED rather than stretched, so the stone keeps its grain at any size. lift brightens
    the stone but not its outline or bevel line - the under-the-mouse state."""
    from PIL import Image
    s = src.crop((2, 2, 70, 34))              # the stone inside its 72x36 tile (the rest is key)
    sw, sh, k = s.width, s.height, 5          # k: the notched corner and its two edge lines
    out = Image.new('RGB', (w, h), KEY)

    def tile(region, dx, dy, dw, dh):
        piece = s.crop(region)
        for yy in range(dy, dy + dh, piece.height):
            for xx in range(dx, dx + dw, piece.width):
                out.paste(piece.crop((0, 0, min(piece.width, dx + dw - xx), min(piece.height, dy + dh - yy))), (xx, yy))
    tile((k, k, sw - k, sh - k), k, k, w - 2 * k, h - 2 * k)                 # face
    tile((k, 0, sw - k, k), k, 0, w - 2 * k, k)                               # top
    tile((k, sh - k, sw - k, sh), k, h - k, w - 2 * k, k)                     # bottom
    tile((0, k, k, sh - k), 0, k, k, h - 2 * k)                               # left
    tile((sw - k, k, sw, sh - k), w - k, k, k, h - 2 * k)                     # right
    for cx, cy in ((0, 0), (w - k, 0), (0, h - k), (w - k, h - k)):          # corners
        sx = 0 if cx == 0 else sw - k
        sy = 0 if cy == 0 else sh - k
        out.paste(s.crop((sx, sy, sx + k, sy + k)), (cx, cy))
    if lift:
        px = out.load()
        for yy in range(h):
            for xx in range(w):
                p = px[xx, yy]
                if p not in (KEY, OUTLINE, BEVEL):
                    px[xx, yy] = tuple(min(255, c + lift) for c in p)
    return out


def sheet(tiles):
    from PIL import Image
    w, h = tiles[0].size
    out = Image.new('RGB', (w * len(tiles), h), KEY)
    for i, t in enumerate(tiles):
        out.paste(t, (i * w, 0))
    return out


def sprites():
    """{name: (image, 'WxH')}"""
    cb = load_rgb('combatboxes')
    grey, red = cb.crop((0, 0, 72, 36)), cb.crop((72, 0, 144, 36))
    return {
        'questtab_icons': (sheet(icons()), '15x15'),
        'questtab_tab': (sheet([stone(grey, TAB_W, TAB_H), stone(red, TAB_W, TAB_H), stone(grey, TAB_W, TAB_H, 36)]),
                         '%dx%d' % (TAB_W, TAB_H)),
        'questtab_button': (sheet([stone(grey, BOX_W, 26), stone(grey, BOX_W, 26, 30)]), '%dx26' % BOX_W),
    }


# ------------------------------------------------------------------------------------ components
class Page:
    """One interface's components, in draw order."""

    def __init__(self, active):
        self.coms = []
        self.active = active

    def add(self, name, **kv):
        self.coms.append((name, kv))

    # -- the parts every page has
    def tabs(self):
        """The button row. The page's own button is the lit stone with no option; the others are
        buttons, and each shows its lit copy (a hidden layer, <name>_hover) under the mouse - the way
        house_options.if lights its close X."""
        for k, (_, _, label) in enumerate(PAGES):
            x = TAB_X + k * TAB_PITCH
            n = 'tab_%s' % PAGES[k][0]
            if k == self.active:
                self.add(n, type='graphic', x=x, y=TAB_Y, width=TAB_W, height=TAB_H, graphic='questtab_tab,1')
            else:
                self.add(n, type='graphic', x=x, y=TAB_Y, buttontype='normal', overlayer=n + '_hover',
                         width=TAB_W, height=TAB_H, graphic='questtab_tab,0', option=label)
            self.add(n + '_icon', type='graphic', x=x + 11, y=TAB_Y + 4, width=15, height=15,
                     graphic='questtab_icons,%d' % k)
        # the lit copies last, so they draw over the row
        for k in range(len(PAGES)):
            if k == self.active:
                continue
            x = TAB_X + k * TAB_PITCH
            n = 'tab_%s' % PAGES[k][0]
            self.add(n + '_hover', type='layer', x=x, y=TAB_Y, width=TAB_W, height=TAB_H, hide='yes')
            self.add(n + '_lit', layer=n + '_hover', type='graphic', x=0, y=0, width=TAB_W, height=TAB_H,
                     graphic='questtab_tab,2')
            self.add(n + '_lit_icon', layer=n + '_hover', type='graphic', x=11, y=4, width=15, height=15,
                     graphic='questtab_icons,%d' % k)

    def title(self, text):
        self.add('title', type='text', x=TITLE_X, y=TITLE_Y, width=TITLE_W, height=TITLE_H, font='b12_full',
                 shadowed='yes', text=text, colour=TITLE)

    # -- building blocks
    def box(self, name, x, y, w, h, dark=146):
        """A box set into the stone: a translucent black face (dark is the old format's trans - 0
        opaque, 255 invisible) inside a 1px rim, dark along the top and left, brown along the
        bottom and right."""
        self.add(name, type='rect', x=x + 1, y=y + 1, width=w - 2, height=h - 2, fill='yes', colour='0x000000',
                 trans=dark)
        self.add(name + '_rim', type='rect', x=x, y=y, width=w, height=h, colour=RIM)
        self.add(name + '_top', type='rect', x=x, y=y, width=w - 1, height=1, fill='yes', colour=EDGE)
        self.add(name + '_left', type='rect', x=x, y=y, width=1, height=h - 1, fill='yes', colour=EDGE)

    def text(self, name, x, y, w, text='', colour=ORANGE, font='p12_full', center=False, h=15, **kv):
        d = dict(type='text', x=x, y=y, width=w, height=h)
        d.update(kv)
        if center:
            d['center'] = 'yes'
        d.update(font=font, shadowed='yes', text=text, colour=colour)
        self.coms.append((name, d))

    def button(self, name, x, y, label, option, icon=None):
        """The wide stone button: the grey stone, its label, and - under the mouse - the lit stone
        with the label in white."""
        self.add(name, type='graphic', x=x, y=y, buttontype='normal', overlayer=name + '_hover', width=BOX_W,
                 height=26, graphic='questtab_button,0', option=option)
        if icon is not None:
            self.add(name + '_icon1', type='graphic', x=x + 8, y=y + 5, width=15, height=15,
                     graphic='questtab_icons,%d' % icon)
            self.add(name + '_icon2', type='graphic', x=x + BOX_W - 23, y=y + 5, width=15, height=15,
                     graphic='questtab_icons,%d' % icon)
        self.text(name + '_label', x, y + 6, BOX_W, label, ORANGE, 'b12_full', center=True)
        self.add(name + '_hover', type='layer', x=x, y=y, width=BOX_W, height=26, hide='yes')
        self.add(name + '_lit', layer=name + '_hover', type='graphic', x=0, y=0, width=BOX_W, height=26,
                 graphic='questtab_button,1')
        if icon is not None:
            self.add(name + '_lit_icon1', layer=name + '_hover', type='graphic', x=8, y=5, width=15, height=15,
                     graphic='questtab_icons,%d' % icon)
            self.add(name + '_lit_icon2', layer=name + '_hover', type='graphic', x=BOX_W - 23, y=5, width=15,
                     height=15, graphic='questtab_icons,%d' % icon)
        self.text(name + '_lit_label', 0, 6, BOX_W, label, WHITE, 'b12_full', center=True, layer=name + '_hover')

    def link(self, name, x, y, w, label, option, h=19):
        """A row of the Quick actions list: its text, and under the mouse a lit strip behind it with
        the text in white."""
        self.add(name, type='rect', x=x, y=y, buttontype='normal', overlayer=name + '_hover', width=w, height=h,
                 fill='yes', colour='0x000000', trans=255, option=option)
        self.text(name + '_label', x + 8, y + 2, w - 8, label, ORANGE)
        self.add(name + '_hover', type='layer', x=x, y=y, width=w, height=h, hide='yes')
        self.add(name + '_lit', layer=name + '_hover', type='rect', x=0, y=0, width=w, height=h, fill='yes',
                 colour='0x8C7F63', trans=190)
        self.text(name + '_lit_label', 8, 2, w - 8, label, WHITE, layer=name + '_hover')


