    for key, x, label, colour, y in (('combat', 4, 'Combat Level', WHITE, 69), ('total', 96, 'Total Level', WHITE, 69),
                                     ('quests', 4, 'Quests Done', GREEN, 129), ('qp', 96, 'Quest Points', GREEN, 129)):
        p.box(key + '_box', x, y, 90, 34)
        p.text(key + '_label', x, y + 3, 90, label, ORANGE, center=True)
        p.text(key, x, y + 17, 90, '', colour, center=True)
    p.box('xp_box', BOX_X, 106, BOX_W, 20)
    p.text('xp', BOX_X, 109, BOX_W, '', ORANGE, center=True)
