    p.text('collections', BOX_X, 198, BOX_W, '', ORANGE, center=True)
    p.box('mode_box', BOX_X, 218, BOX_W, 20)
    p.text('mode', BOX_X, 221, BOX_W, '', ORANGE, center=True)
    p.box('online_box', BOX_X, 241, BOX_W, 17, dark=40)
    p.text('online', BOX_X, 242, BOX_W, '', ORANGE, center=True)
