# Server Statistics' Quick actions: (key, label, option). Report a player and Discord, in the mock-up,
# are not here: the server cannot open the client's report window (the client only arms its typing
# for the window when it opened it itself), and there is no Discord invite anywhere to point at.
ACTIONS = [('drops', 'View monster drop tables', 'View @lre@Monster drop tables'),
           ('bosses', 'View boss kill counts', 'View @lre@Boss kill counts'),
           ('collog', 'Open collection log', 'Open @lre@Collection Log'),
           ('mode', 'Game mode & XP rate', 'View @lre@Game mode & XP rate')]


def sstats():
    p = Page(4)
    p.tabs()
    p.title('Server Statistics')
    for k, (key, dark) in enumerate((('online', 40), ('time', 146), ('uptime', 146), ('slogan', 146))):
        y = BODY_TOP + k * 23
        p.box(key + '_box', BOX_X, y, BOX_W, 20, dark=dark)
        p.text(key, BOX_X, y + 3, BOX_W, 'The true golden era.' if key == 'slogan' else '',
               YELLOW if key == 'slogan' else ORANGE, center=True)
    top = BODY_TOP + 4 * 23 + 2
    p.box('actions_box', BOX_X, top, BOX_W, BODY_BOTTOM - top)
    p.text('actions_title', 10, top + 4, 170, 'Quick actions', YELLOW, 'b12_full')
    for k, (key, label, option) in enumerate(ACTIONS):
        y = top + 22 + k * 21
        if k:
            p.add('act_%s_rule' % key, type='rect', x=BOX_X + 6, y=y - 1, width=BOX_W - 12, height=1, fill='yes',
                  colour=RULE)
        p.link('act_' + key, BOX_X + 3, y, BOX_W - 6, label, option)
    return p


# ------------------------------------------------------------------------------------ writers
ORDER = ['layer', 'type', 'x', 'y', 'buttontype', 'overlayer', 'width', 'height', 'hide', 'center', 'font',
         'shadowed', 'fill', 'graphic', 'text', 'colour', 'trans', 'option']


def emit(coms):
    out = []
    for name, c in coms:
        out.append('[%s]' % name)
        for k in ORDER:
            if k in c:
                out.append('%s=%s' % (k, c[k]))
        extra = [k for k in c if k not in ORDER]
        if extra:
            raise SystemExit('genquesttab: unknown interface key %s on %s' % (extra, name))
        out.append('')
    return '\n'.join(out).rstrip('\n') + '\n'


HEAD = ('// GENERATED by tools/genquesttab.py - do not hand-edit. The quest tab\'s %s page; its texts are\n'
        '// filled by questtab/scripts/questtab.rs2 each time it is shown.\n')


def interfaces(tabs):
    return {'questtab_summary': summary(), 'questtab_collection': collection(tabs), 'questtab_pstats': pstats(),
            'questtab_sstats': sstats()}


MARK = '// APPENDED by tools/genquesttab.py'


def patch_questlist(text):
    """The button row, in its own marked block immediately before [qp]. [qp] is genquest474's, and
    neither genbosskills nor gencollectionlog goes near it (they work at the end of the file), so
    all four generators can run in any order and the file comes out the same."""
    t = text.replace('\r\n', '\n')
    i = t.find(MARK)
    if i >= 0:
        end = t.find('\n[qp]\n', i)
        if end < 0:
            raise SystemExit('genquesttab: my block in questlist.if is not followed by [qp]')
        t = t[:i].rstrip('\n') + '\n\n' + t[end + 1:]
    at = t.find('\n[qp]\n')
    if at < 0:
        raise SystemExit('genquesttab: questlist.if has no [qp] - run LostCityServer tools/models/genquest474.py')
    p = Page(1)
    p.tabs()
    block = (MARK + ' - do not hand-edit. The quest tab\'s button row, the same on all five\n'
             '// pages; the triggers are in questtab/scripts/questtab_tabs.rs2.\n' + emit(p.coms))
    return t[:at + 1] + block + '\n' + t[at + 1:]


def build_constant():
    L = ['// GENERATED by tools/genquesttab.py - do not hand-edit.',
         '//',
         '// The quest tab\'s pages, in the order of the button row. %questtab_page holds one of these.']
    for k, (key, _, _) in enumerate(PAGES):
        L.append('^questtab_%s = %d' % (key, k))
    L.append('^questtab_pages = %d' % len(PAGES))
    L.append('')
    L.append('// The Collection Log page\'s bar: its width, and the pixels the fill is moved left by for a share of it.')
    L.append('^questtab_bar_width = %d' % CL_BAR_W)
    L.append('// How far right-aligned values reach: each value component starts at x and is this wide.')
    L.append('^questtab_pstats_value_width = %d' % PS_VALUE_W)
    L.append('^questtab_collection_count_width = %d' % CL_COUNT_W)
    return '\n'.join(L) + '\n'


def build_enum(tabs):
    L = ['// GENERATED by tools/genquesttab.py - do not hand-edit.',
         '//',
         '// The Collection Log page\'s rows by collection log tab number, so ~questtab_collection_draw can',
         '// walk the tabs rather than name each row: the engine cannot pick a component by number.']
    for what in ('name', 'count', 'fill'):
        L += ['', '[questtab_collection_%s]' % what, 'inputtype=int', 'outputtype=component']
        for k in range(len(tabs)):
            L.append('val=%d,questtab_collection:row%d_%s' % (k, k, what))
    return '\n'.join(L) + '\n'


def build_rs2():
    L = ['// GENERATED by tools/genquesttab.py - do not hand-edit.',
         '//',
         '// The quest tab\'s button row: on every page, each of the other four buttons selects its page.',
         '// The page\'s own button is not a button, so it has no trigger.',
         '',
         '// Show a page\'s interface in the quest tab slot. ~questtab_show fills its texts first.',
         '[proc,questtab_settab](int $page)',
         'switch_int ($page) {']
    for key, iface, _ in PAGES:
        L.append('    case ^questtab_%s : if_settab(%s, ^tab_quest_journal);' % (key, iface))
    L.append('}')
    for _, iface, _ in PAGES:
        L.append('')
        for key, other, _ in PAGES:
            if other != iface:
                L.append('[if_button,%s:tab_%s] ~questtab_select(^questtab_%s);' % (iface, key, key))
    return '\n'.join(L) + '\n'


# ------------------------------------------------------------------------------------ main
def read(p):
    return open(p, encoding='utf-8', newline='').read() if os.path.exists(p) else None


def crlf_of(path, like):
    t = read(path) if os.path.exists(path) else read(like)
    return t is not None and '\r\n' in t


def main():
    check = '--check' in sys.argv
    tabs = json.load(open(CLOGSPEC, encoding='utf-8'))['tabs']
    like = QUESTLIST
    want = {}
    for name, page in interfaces(tabs).items():
        which = name.split('_', 1)[1]
        want[os.path.join(DIR, 'interfaces', name + '.if')] = HEAD % dict(summary='Character Summary',
            collection='Collection Log', pstats='Player Statistics', sstats='Server Statistics')[which] + emit(page.coms)
    want[os.path.join(DIR, 'configs', 'questtab.constant')] = build_constant()
    want[os.path.join(DIR, 'configs', 'questtab.enum')] = build_enum(tabs)
    want[os.path.join(DIR, 'scripts', 'questtab_tabs.rs2')] = build_rs2()
    want[QUESTLIST] = patch_questlist(read(QUESTLIST))

    changed = []
    for path, body in want.items():
        nl = '\r\n' if crlf_of(path, like) else '\n'
        body = body.replace('\r\n', '\n').replace('\n', nl)
        if read(path) != body:
            changed.append(os.path.relpath(path, C))
            if not check:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                open(path, 'w', encoding='utf-8', newline='').write(body)

    from PIL import Image, ImageChops
    for name, (img, opt) in sprites().items():
        png = os.path.join(SPRITES, name + '.png')
        meta = os.path.join(SPRITES, 'meta', name + '.opt')
        same = os.path.exists(png) and Image.open(png).convert('RGB').size == img.size and \
            ImageChops.difference(Image.open(png).convert('RGB'), img).getbbox() is None
        if not same:
            changed.append(os.path.relpath(png, C))
            if not check:
                img.save(png)
        if read(meta) is None or read(meta).strip() != opt:
            changed.append(os.path.relpath(meta, C))
            if not check:
                open(meta, 'w', newline='').write(opt + '\n')

    names = [p[1] for p in PAGES]
    if check:
        packed = set(re.findall(r'^\d+=(\S+?)\r?$', read(ifids.PACK), re.M))
        ids_ok = all(n in packed for n in names) and all(
            '%s:%s' % (n, c) in packed for n in names if n != 'questlist'
            for c, _ in interfaces(tabs)[n].coms)
        if changed or not ids_ok:
            print('genquesttab --check: would change %s' % ', '.join(changed + ([] if ids_ok else ['interface.pack'])))
            return 1
        print('genquesttab --check: everything is already what this writes')
        return 0
    for line in ifids.sync(names):
        print(line)
    print('genquesttab: %d files changed%s' % (len(changed), ''.join('\n  ' + c for c in changed)))
    return 0


if __name__ == '__main__':
    sys.exit(main())
